package model;

public class Employee {
   private final String code;
   private String fullName;
   private String phone;
   private String email;
   private Role role;
   private boolean active;
 /**
     * Creates an active employee.
     *
     * <b>Pre:</b> the code is unique and the full name and the role are not empty.<br>
     * <b>Post:</b> an active employee with the given data is created.
     *
     * @param code unique code generated by the system, not null
     * @param fullName full name, not empty
     * @param phone phone number
     * @param email contact email
     * @param role keeper or veterinarian, not null
     */
   public Employee(String var1, String var2, String var3, String var4, Role var5) {
      this.code = var1;
      this.fullName = var2;
      this.phone = var3;
      this.email = var4;
      this.role = var5;
      this.active = true;
   }
 /**
     * Gets the employee code.
     *
     * <b>Pre:</b> the object has been created.<br>
     * <b>Post:</b> no data is modified.
     *
     * @return the unique code
     */
   public String getCode() {
      return this.code;
   }
 /**
     * Gets the full name.
     *
     * <b>Pre:</b> the object has been created.<br>
     * <b>Post:</b> no data is modified.
     *
     * @return the full name
     */
   public String getFullName() {
      return this.fullName;
   }
 /**
     * Changes the full name.
     *
     * <b>Pre:</b> the new full name is not empty.<br>
     * <b>Post:</b> the full name is replaced by the new value.
     *
     * @param fullName the new name, not empty
     */
   public void setFullName(String var1) {
      this.fullName = var1;
   }
/**
     * Gets the phone.
     *
     * <b>Pre:</b> the object has been created.<br>
     * <b>Post:</b> no data is modified.
     *
     * @return the phone number
     */
   public String getPhone() {
      return this.phone;
   }
 /**
     * Changes the phone.
     *
     * <b>Pre:</b> the new phone has a valid format (digits only).<br>
     * <b>Post:</b> the phone is replaced by the new value.
     *
     * @param phone the new phone number
     */
   public void setPhone(String var1) {
      this.phone = var1;
   }

    /**
     * Gets the email.
     *
     * <b>Pre:</b> the object has been created.<br>
     * <b>Post:</b> no data is modified.
     *
     * @return the contact email
     */
   public String getEmail() {
      return this.email;
   }
 /**
     * Changes the email.
     *
     * <b>Pre:</b> the new email has a valid format.<br>
     * <b>Post:</b> the email is replaced by the new value.
     *
     * @param email the new email
     */
   public void setEmail(String var1) {
      this.email = var1;
   }
 /**
     * Gets the role.
     *
     * <b>Pre:</b> the object has been created.<br>
     * <b>Post:</b> no data is modified.
     *
     * @return the role of the employee
     */
   public Role getRole() {
      return this.role;
   }
/**
     * Changes the role.
     *
     * <b>Pre:</b> the new role is not null.<br>
     * <b>Post:</b> the role is replaced by the new value.
     *
     * @param role the new role, not null
     */
   public void setRole(Role var1) {
      this.role = var1;
   }

    /**
     * Tells if the employee is active.
     *
     * <b>Pre:</b> the object has been created.<br>
     * <b>Post:</b> no data is modified.
     *
     * @return true if active, false if inactive
     */
   public boolean isActive() {
      return this.active;
   }
 /**
     * Changes the state of the employee.
     *
     * <b>Pre:</b> none (any boolean value is accepted).<br>
     * <b>Post:</b> the active is replaced by the new value.
     *
     * @param active true for active, false for inactive
     */
   public void setActive(boolean var1) {
      this.active = var1;
   }
 /**
     * Builds a text with all the data of the employee.
     *
     * <b>Pre:</b> the object has been created.<br>
     * <b>Post:</b> no data is modified.
     *
     * @return a multi-line description
     */
   public String getDetails() {
      String var10000 = this.code;
      return "Code: " + var10000 + "\nName: " + this.fullName + "\nPhone: " + this.phone + "\nEmail: " + this.email + "\nRole: " + String.valueOf(this.role) + "\nStatus: " + (this.active ? "Active" : "Inactive");
   }
}
